	public void requestFocus() {
		diffPlugin.getListingPanel().getFieldPanel().requestFocus();
	}

	/* @Override */
	public bool isVisible() {
		// Is the CodeViewer visible and the Diff visible?
		return navigatable.isVisible() && diffPlugin.isShowingDiff();
	}

